import { runYamlTransform } from './core/run-yaml-transform.mjs';
import { writeStderr, writeStdout } from './core/write-bytes.mjs';

function getProgramName(rawArgv) {
  return basename(rawArgv[1] ?? 'test14.mjs');
}

export function main(rawArgv = process.argv) {
  const programName = getProgramName(rawArgv);
  const parsed = parseCommandLine(rawArgv, programName);

  if (parsed.kind === 'help') {
    writeStdout(buildHelp(programName));
    return 0;
