function isOptionLike(token) {
  return token.startsWith('-') && token !== '-';
}

export function parseArgv(argv) {
  let aValue;
  let hasA = false;
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      unknown.push(...argv.slice(index + 1));
      break;
    }

    if (token === '-h' || token === '--help') {
      return { kind: 'help' };
    }

    if (token === '--a') {
      const next = argv[index + 1];

      if (next === undefined || isOptionLike(next)) {
        return { kind: 'error', errorType: 'missingValue' };
      }

      aValue = next;
      hasA = true;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      hasA = true;
      continue;
    }

    unknown.push(token);
  }

  if (!hasA) {
    return { kind: 'error', errorType: 'missingRequired' };
  }

  if (unknown.length > 0) {
    return { kind: 'error', errorType: 'unrecognized', unknown };
  }

  return { kind: 'success', a: aValue };
}

